-- Expected grants once ratified:  GRANT INSERT,UPDATE ON mandate TO <owner>;
--                                 GRANT SELECT ON mandate TO ctv_svc;
-- ==========================================================================
CREATE TABLE IF NOT EXISTS mandate (
    id                     UUID         NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
    mandate_ref            VARCHAR(35)  NOT NULL,
    contract_ref           VARCHAR(14)  NOT NULL,
    creditor_account                 VARCHAR(32)  NOT NULL,
    product_code           VARCHAR(8)   NOT NULL,
    debtor_account          VARCHAR(32)  NOT NULL,
    debtor_branch          VARCHAR(16)  NOT NULL,
    debtor_name            VARCHAR(70)  NOT NULL,
    currency               CHAR(3)      NOT NULL DEFAULT 'ZAR',
    max_collection_amount  DECIMAL(18,2) NOT NULL,
    frequency              VARCHAR(4)   NOT NULL,
    collection_day         INT2         NOT NULL,
    status                 VARCHAR(16)  NOT NULL,
    client_id              VARCHAR(16)  NOT NULL,
    start_date             DATE         NOT NULL,
    expiry_date            DATE             NULL,
    created_at             TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at             TIMESTAMPTZ  NOT NULL DEFAULT now() ON UPDATE now(),
    CONSTRAINT uq_mandate_ref UNIQUE (mandate_ref),
    CONSTRAINT ck_mandate_status CHECK (status IN ('PENDING','ACTIVE','SUSPENDED','CANCELLED','EXPIRED')),
    CONSTRAINT ck_mandate_amount CHECK (max_collection_amount >= 0),
    CONSTRAINT ck_mandate_currency CHECK (currency = 'ZAR'),
    CONSTRAINT ck_mandate_day CHECK (collection_day BETWEEN 1 AND 31),
    CONSTRAINT ck_mandate_window CHECK (expiry_date IS NULL OR expiry_date >= start_date)
);
-- R-20 (client-scoped, effective-window): at most one EFFECTIVELY ACTIVE
-- mandate per (client_id, creditor_account, contract_ref), enforced over
-- overlapping validity windows, not stored status alone (Fugu F28/F29).
-- Production mints this as a non-overlap constraint / transactionally
-- maintained effective-state table via Liquibase; the fixture layer enforces
-- it in Python (check_invariants + verifier).
CREATE INDEX IF NOT EXISTS ix_mandate_client_acct_contract
    ON mandate (client_id, creditor_account, contract_ref);
CREATE INDEX IF NOT EXISTS ix_mandate_creditor_account ON mandate (creditor_account);

